    NO MAXVALUE
    CACHE 1
);


--
-- Name: tenant_billing_state; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.tenant_billing_state (
    tenant_id bigint NOT NULL,
    status character varying(20) NOT NULL,
    grace_until timestamp with time zone,
    last_payment_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT tenant_billing_state_status_check CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'WARNING'::character varying, 'GRACE'::character varying, 'SUSPENDED'::character varying])::text[])))
);


ALTER TABLE public.tenant_billing_state OWNER TO postgres;

